export const stagingSources={stagingRoom:'room-color-v62.png',stagingShelf:'wooden-shelf-v62.png',stagingStreet:'war-street-v62.png',stagingSoldier:'street-figure-v62.png'};
export const stagingDefaults={stagingRoomEnabled:true,stagingFillInteriors:true,stagingBoyDepth:1.4,stagingBasinDepth:2.2,stagingShelfDepth:.8,stagingForegroundStrength:0,stagingStreetEnabled:true,stagingMatWidth:68,stagingMatColor:'#696765',stagingColorStart:3.8,stagingColorEnd:5.2,stagingMotherExitStart:4.55,stagingMotherExitEnd:5.25,stagingBoyStart:3.6,stagingBoyEnd:4.5,stagingRoomPush:.72,stagingRoomFocusX:.5,stagingRoomFocusY:.45,stagingBoyX:205,stagingBoyY:60,stagingBoyWidth:555,stagingBoyLight:.91,stagingMotherX:480,stagingMotherY:72,stagingMotherWidth:405,stagingShelfX:745,stagingShelfY:205,stagingShelfWidth:190,stagingShelfLight:.68,stagingClothX:225,stagingClothY:294,stagingClothWidth:135,stagingBasinX:-160,stagingBasinY:355,stagingBasinWidth:475,stagingRoomLight:.86,stagingFaceShadow:.43,stagingStreetPush:.34,stagingStreetFocusX:.5,stagingStreetFocusY:.43,stagingStreetLight:.72,stagingStreetReveal:1.1,stagingStreetPersonX:480,stagingStreetPersonFeet:485,stagingStreetPersonHeight:245,stagingStreetPersonGrowth:340,stagingStreetPersonLight:.72,stagingElectricalDepth:1,stagingPoleLean:75,stagingFailureStart:12.9,stagingFailureDuration:2.7,stagingSparkLifetime:.13,stagingSparkSize:1.3,stagingSparkCount:16,stagingSparkStop:19.7,stagingSmokeOpacity:.98};
const clamp=x=>Math.max(0,Math.min(1,x)),smooth=x=>{x=clamp(x);return x*x*(3-2*x)},mix=(a,b,q)=>a+(b-a)*q;
export const stageMedia=(images,f,slot)=>images[f.historySourceBindings?.[slot]||slot];
const cropCache=new WeakMap();function cropImage(im){if(!(im?.naturalWidth||im?.width))return null;const old=cropCache.get(im);if(old&&old.src===im.src&&old.revision===im._assetRevision)return old;const w=im.naturalWidth||im.width,h=im.naturalHeight||im.height,cv=Object.assign(document.createElement('canvas'),{width:w,height:h}),cx=cv.getContext('2d');cx.drawImage(im,0,0);const p=cx.getImageData(0,0,w,h);let minX=w,minY=h,maxX=0,maxY=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=(y*w+x)*4;if(p.data[i+3]<95)p.data[i+3]=0;else{minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}}cx.putImageData(p,0,0);const value={canvas:cv,x:minX,y:minY,w:Math.max(1,maxX-minX+1),h:Math.max(1,maxY-minY+1),src:im.src,revision:im._assetRevision};cropCache.set(im,value);return value;}
export function paintStagingSprite(c,images,f,slot,x,y,width,{height,alpha=1,gray=0,light=1,shadow=0}={}){const im=stageMedia(images,f,slot),a=cropImage(im);if(!a)return null;const h=height??width*a.h/a.w;c.save();c.globalAlpha*=clamp(alpha);c.filter=`grayscale(${gray}) brightness(${light})`;let drawn=a.canvas,sx=a.x,sy=a.y,sw=a.w,sh=a.h;if(shadow){a.shades??=new Map();if(!a.shades.has(shadow)){const cv=Object.assign(document.createElement('canvas'),{width:a.w,height:a.h}),cx=cv.getContext('2d');cx.drawImage(a.canvas,a.x,a.y,a.w,a.h,0,0,a.w,a.h);cx.globalCompositeOperation='source-atop';const g=cx.createLinearGradient(a.w*.4,0,a.w,0);g.addColorStop(0,'#0000');g.addColorStop(1,`rgba(0,0,0,${shadow})`);cx.fillStyle=g;cx.fillRect(0,0,a.w,a.h);a.shades.set(shadow,cv);}drawn=a.shades.get(shadow);sx=0;sy=0;}c.drawImage(drawn,sx,sy,sw,sh,x,y,width,h);c.filter='none';recordSceneAsset(c,{id:slot,kind:'image',assetSlot:slot,name:slot},[x,y,width,h]);c.restore();return [x,y,width,h];}
export function stagingRoomState(time,input={}){const f={...hybridDefaults,...stagingDefaults,...input},between=(a,b)=>smooth((time-a)/Math.max(.05,b-a));return {color:between(f.stagingColorStart,f.stagingColorEnd),boy:between(f.stagingBoyStart,f.stagingBoyEnd),mother:1-between(f.stagingMotherExitStart,f.stagingMotherExitEnd),push:1+f.stagingRoomPush*smooth((time-4.9)/6.7)};}
export function paintReferenceRoom(c,time,images,input={}){const f={...hybridDefaults,...stagingDefaults,...input},s=stagingRoomState(time,f),im=stageMedia(images,f,'stagingRoom');if(!im)return false;c.save();const fx=960*f.stagingRoomFocusX,fy=540*f.stagingRoomFocusY;c.translate(fx,fy);c.scale(s.push,s.push);c.translate(-fx,-fy);c.filter=`grayscale(${1-s.color}) brightness(${f.stagingRoomLight})`;c.drawImage(im,0,0,960,540);c.filter='none';const layer=(slot,x,y,w,options={},depth=1)=>{const gain=1+(s.push-1)*(depth-1),X=fx+(x-fx)*gain,Y=fy+(y-fy)*gain;return paintStagingSprite(c,images,f,slot,X,Y,w*gain,options)};layer('stagingShelf',f.stagingShelfX,f.stagingShelfY,f.stagingShelfWidth,{gray:1-s.color,light:f.stagingShelfLight},f.stagingShelfDepth);layer('historyRoomCloth',f.stagingClothX,f.stagingClothY,f.stagingClothWidth,{gray:1-s.color,light:.88});layer('historyMotherPerson',f.stagingMotherX,f.stagingMotherY,f.stagingMotherWidth,{alpha:s.mother,gray:1,light:.68});layer('continuationBoyColor',f.stagingBoyX,f.stagingBoyY,f.stagingBoyWidth,{alpha:s.boy,gray:1-s.color,light:f.stagingBoyLight,shadow:f.stagingFaceShadow},f.stagingBoyDepth);layer('historyRoomVase',f.stagingBasinX,f.stagingBasinY,f.stagingBasinWidth,{gray:1-s.color,light:.62},f.stagingBasinDepth);c.restore();return s;}
export function electricalFailureState(time,input={}){const f={...hybridDefaults,...stagingDefaults,...input},age=time-f.stagingFailureStart,q=clamp(age/Math.max(.1,f.stagingFailureDuration));return {age,collapse:smooth(q),sparks:age>=0&&time<f.stagingSparkStop};}
function wire(c,a,b,sag,color,width){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(...a);c.quadraticCurveTo((a[0]+b[0])/2,(a[1]+b[1])/2+sag,...b);c.stroke();}
export function paintElectricalFailure(c,time,input={},push=0){if(input.hybridStreetEnabled!==false)return paintHybridWires(c,time,input);const f={...hybridDefaults,...stagingDefaults,...input},s=electricalFailureState(time,f),depth=Math.max(.2,f.stagingElectricalDepth);c.save();c.translate(480,245);c.scale((1+push*.5)*depth,(1+push*.5)*depth);c.translate(-480,-245);const ends=[];for(let i=0;i<5;i++){const base=[250+i*70,300-i*9],height=145-i*10,fall=smooth((s.collapse-i*.06)/.76),angle=(f.stagingPoleLean+i*5)*Math.PI/180*fall,tip=[base[0]-Math.sin(angle)*height,base[1]-Math.cos(angle)*height];ends.push(tip);c.strokeStyle='#5c5d58';c.lineWidth=3-i*.25;c.beginPath();c.moveTo(...base);c.lineTo(...tip);c.stroke();const arm=28-i*3;c.strokeStyle='#898b80';c.lineWidth=1.4;c.beginPath();c.moveTo(tip[0]-arm,tip[1]+8);c.lineTo(tip[0]+arm,tip[1]-8);c.stroke();for(let j=-1;j<=1;j++){wire(c,[tip[0]+j*arm*.6,tip[1]+8],[825,155+j*27],8+s.collapse*(40+i*11),'#666960',.8);if(i)wire(c,ends[i-1],[tip[0]+j*10,tip[1]],12+s.collapse*55,'#82857b',.9);}}
// Finite localized burst emitters, no persistent paper-like streams.
if(s.sparks){for(let emitter=0;emitter<3;emitter++){const initial=f.stagingFailureStart+emitter*.6,contact=f.stagingFailureStart+f.stagingFailureDuration*.82+emitter*.12,onset=time>=contact?contact:initial,age=time-onset;if(age<0||age>(time>=contact?.35:1.1))continue;const cycle=Math.floor(age/.18),local=age-cycle*.18;if(local>f.stagingSparkLifetime)continue;const origin=ends[emitter+1],life=local/f.stagingSparkLifetime;for(let i=0;i<Math.max(0,Math.min(50,f.stagingSparkCount));i++){const angle=i*2.399+cycle*1.7,v=14+(i*13%39),x=origin[0]+Math.cos(angle)*v*local,y=origin[1]+Math.sin(angle)*v*local+45*local*local;c.globalAlpha=(1-life)*(f.expansionSparkStrength??1);c.fillStyle=i%3?'#ffc14c':'#fff7c2';c.shadowColor='#ffb330';c.shadowBlur=3;c.beginPath();c.arc(x,y,f.stagingSparkSize*(1-life*.5),0,Math.PI*2);c.fill();}}}c.restore();return s;}
const plateCache=new WeakMap();export function opaqueStreetPlate(im){if(!(im?.naturalWidth||im?.width))return null;const prior=plateCache.get(im);if(prior&&prior.src===im.src&&prior.revision===im._assetRevision)return prior.canvas;const w=im.naturalWidth||im.width,h=im.naturalHeight||im.height,cv=Object.assign(document.createElement('canvas'),{width:w,height:h}),cx=cv.getContext('2d');cx.drawImage(im,0,0);const pixels=cx.getImageData(0,0,w,h),p=pixels.data,visited=new Uint8Array(w*h),queue=new Uint32Array(w*h);let read=0,write=0;const add=i=>{if(!visited[i]&&p[i*4+3]<128){visited[i]=1;queue[write++]=i}};for(let x=0;x<w;x++){add(x);add((h-1)*w+x)}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1)}while(read<write){const i=queue[read++],x=i%w;if(x)add(i-1);if(x<w-1)add(i+1);if(i>=w)add(i-w);if(i<w*(h-1))add(i+w)}for(let i=0;i<w*h;i++)if(!visited[i]){if(p[i*4+3]<128){p[i*4]=p[i*4+1]=p[i*4+2]=18;}p[i*4+3]=255;}cx.putImageData(pixels,0,0);plateCache.set(im,{canvas:cv,src:im.src,revision:im._assetRevision});return cv;}
export function paintStreetPlate(c,time,images,input={}){if(input.hybridStreetEnabled!==false){const im=stageMedia(images,input,'stagingStreet');if(im)return paintHybridStreetPlate(c,time,input.stagingFillInteriors!==false?opaqueStreetPlate(im):im,input);}const f={...hybridDefaults,...stagingDefaults,...input},im=stageMedia(images,f,'stagingStreet');if(!im)return false;const q=clamp((time-13.3)/12.1),z=1+f.stagingStreetPush*q,fx=f.stagingStreetFocusX*960,fy=f.stagingStreetFocusY*540;c.save();c.translate(fx,fy);c.scale(z,z);c.translate(-fx,-fy);c.filter=`grayscale(1) brightness(${f.stagingStreetLight})`;c.drawImage(f.stagingFillInteriors?opaqueStreetPlate(im):im,0,0,960,540);c.restore();return {q,z};}
export function paintStreetPerson(c,time,images,input={}){if(input.hybridStreetEnabled!==false){const a=hybridStreetActor(time,input),im=stageMedia(images,input,'stagingSoldier'),crop=cropImage(im);if(!crop)return false;const w=a.height*crop.w/crop.h;return paintStagingSprite(c,images,input,'stagingSoldier',a.x-w/2,a.feet-a.height,w,{height:a.height,gray:1,light:input.stagingStreetPersonLight??.72});}const f={...hybridDefaults,...stagingDefaults,...input},q=clamp((time-13.3)/12.1),h=f.stagingStreetPersonHeight+q*f.stagingStreetPersonGrowth,im=stageMedia(images,f,'stagingSoldier'),a=cropImage(im);if(!a)return false;const w=h*a.w/a.h,feet=f.stagingStreetPersonFeet+q*60;return paintStagingSprite(c,images,f,'stagingSoldier',f.stagingStreetPersonX+q*65-w/2,feet-h,w,{height:h,gray:1,light:f.stagingStreetPersonLight});}
export function lightningEnvelope(time,input={}){const start=input.expansionLightningStart??19.2,strength=input.expansionLightningStrength??.8;let sum=0;for(const event of [start,start+2.2,28.7,30.4]){const age=time-event;if(age>=0)sum+=strength*(Math.exp(-age*15)+Math.exp(-Math.abs(age-.17)*30)*.5);}return Math.min(1,sum);}
export function paintStagingLightning(c,time,input={}){const a=lightningEnvelope(time,input);if(a<.005)return;c.save();c.globalAlpha=a;c.strokeStyle='#d8d7ed';c.lineWidth=1.3;c.shadowColor='#aab4ec';c.shadowBlur=10;c.beginPath();[[685,0],[660,35],[675,35],[640,72],[653,70],[624,115]].forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke();c.restore();}
export function paintStagingFlash(c,time,input={}){const age=time-(input.expansionExplosionStart??13.5),flash=age<0?0:Math.exp(-age*3)*(input.expansionFlashStrength??.65),lightning=lightningEnvelope(time,input);if(flash+lightning<.005)return;c.save();c.globalCompositeOperation='screen';const g=c.createRadialGradient(input.expansionExplosionX??490,input.expansionExplosionY??290,10,480,300,620);g.addColorStop(0,`rgba(255,194,120,${flash*.32})`);g.addColorStop(1,'#ffd8a000');c.fillStyle=g;c.fillRect(0,0,960,540);c.fillStyle=`rgba(194,201,255,${lightning*.1})`;c.fillRect(0,0,960,540);c.restore();}
